import{_ as o,o as t,c as a,a2 as l}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosted/desktop.md","filePath":"zh/self-hosted/desktop.md","lastUpdated":1788855895000}'),r={name:"zh/self-hosted/desktop.md"};function s(i,e,p,h,d,n){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h1><p>Memoh Desktop 是面向 Memoh Cloud 或自托管 Memoh 服务端的原生客户端。它把同一套 Web UI 打包进 Electron 外壳，提供原生窗口、托盘、菜单与快捷键，并且可以把所在的这台电脑注册为机器人可用的 <strong>Computer</strong>。</p><p>Desktop <strong>不会</strong>自己运行本地服务端或数据库。你始终需要把它连到一个 Memoh 服务端：<a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a> 或你自己的 <a href="/zh/self-hosted/docker.html">Server Deploy</a>。</p><h2 id="何时使用-desktop" tabindex="-1">何时使用 Desktop <a class="header-anchor" href="#何时使用-desktop" aria-label="Permalink to &quot;何时使用 Desktop&quot;">​</a></h2><p>适合以下场景：</p><ul><li>想要原生 App 窗口与系统托盘，而不是浏览器标签页</li><li>想用原生菜单与快捷键处理日常的 Memoh 工作流</li><li>想让服务端的机器人使用这台电脑的文件、Shell 与浏览器，又不想单独跑一个 runtime 进程</li></ul><p>如果只是偶尔从浏览器访问，直接用 Web UI 即可。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>从 <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">Memoh Desktop 下载页</a> 下载对应平台的安装包（macOS DMG、Windows NSIS、Linux AppImage/deb/rpm）。</li><li>打开 Memoh。</li><li>在连接页填写服务端地址（或选择 Memoh Cloud）。</li><li>用你的 Memoh 账号登录。</li></ol><h2 id="连接服务端" tabindex="-1">连接服务端 <a class="header-anchor" href="#连接服务端" aria-label="Permalink to &quot;连接服务端&quot;">​</a></h2><p>在连接页输入服务端地址后连接：</p><ul><li>裸域名（如 <code>memoh.example.com</code>）默认按 <code>https://</code> 处理（只有 localhost 地址默认 <code>http://</code>）。</li><li>缺少 <code>/api</code> 后缀时会自动补上，只填域名即可。</li><li>Desktop 会先探测服务端的 <code>/ping</code>（5 秒超时），成功后再进入登录页。</li></ul><p>切换到另一个服务端会清除本地登录状态，需要重新登录。</p><h2 id="把这台电脑共享给机器人" tabindex="-1">把这台电脑共享给机器人 <a class="header-anchor" href="#把这台电脑共享给机器人" aria-label="Permalink to &quot;把这台电脑共享给机器人&quot;">​</a></h2><p>Desktop 可以把它所在的机器注册成服务端机器人可用的 <strong>Computer</strong>，不用另跑 runtime 进程：打开 <strong>这台电脑</strong> 开关，起个名字，Desktop 会通过内嵌的 Memoh runtime SDK 在后台维持连接。凭据使用操作系统的安全存储保存。</p><p>权限模型、按机器人授权以及机器人在电脑上能做什么，见 <a href="/zh/guides/computers.html">Computers</a>。</p><h2 id="desktop-负责什么" tabindex="-1">Desktop 负责什么 <a class="header-anchor" href="#desktop-负责什么" aria-label="Permalink to &quot;Desktop 负责什么&quot;">​</a></h2><ul><li>应用窗口、托盘图标、重新打开与退出行为</li><li>与 Web UI 共用命令注册表的原生菜单</li><li>到所选服务端的连接及其缓存的登录状态</li><li><strong>这台电脑</strong> 对应的可选 Remote Runtime 连接</li></ul><p>其它一切（机器人、会话、记忆、工作区、渠道）都在你连接的服务端上。工作区运行时在服务端配置，见 <a href="/zh/self-hosted/workspace-backends.html">Workspace Backends</a>。</p>',19)])])}const k=o(r,[["render",s]]);export{c as __pageData,k as default};
